/// Return the index of the first element equal to zero.
/// If there is no zero, return `v.len()`.
///
/// Properties ensured:
/// - Result `i` is in `[0, v.len()]`.
/// - For all `j < i`, `v[j] != 0`.
/// - If `i < v.len()`, then `v[i] == 0`.
pub fn mfirst_cero(v: &[i32]) -> usize {
    for (i, &x) in v.iter().enumerate() {
        if x == 0 {
            return i;
        }
    }
    v.len()
}

